/* ---------- window glass effect ---------- */

fn settings_path(app: &AppHandle) -> Option<PathBuf> {
    let dir = app.path().app_data_dir().ok()?;
    let _ = fs::create_dir_all(&dir);
    Some(dir.join("settings.json"))
}

fn read_effect(app: &AppHandle) -> String {
    if let Some(p) = settings_path(app) {
        if let Ok(raw) = fs::read_to_string(p) {
            if let Ok(v) = serde_json::from_str::<Value>(&raw) {
                if let Some(s) = v.get("effect").and_then(|x| x.as_str()) {
                    return s.to_string();
                }
            }
        }
    }
    "blur".to_string()
}

fn write_effect(app: &AppHandle, name: &str) {
    if let Some(p) = settings_path(app) {
        let _ = fs::write(p, serde_json::json!({ "effect": name }).to_string());
    }
}

fn apply_effect(app: &AppHandle, name: &str) {
    let Some(win) = app.get_webview_window("main") else {
        return;
    };
    let config = match name {
        "blur" => EffectsBuilder::new().effect(Effect::Blur).build(),
        "mica" => EffectsBuilder::new().effect(Effect::Mica).build(),
        "none" => EffectsBuilder::new().build(),
        _ => EffectsBuilder::new().effect(Effect::Blur).build(),
    };
    let _ = win.set_effects(config);
}

