.settings-panel {
  position: absolute;
  inset: 0;
  z-index: 50;
  display: flex;
  flex-direction: column;
  padding: var(--s4);
  background: var(--bg);
  backdrop-filter: blur(24px);
  border-radius: var(--radius);
}
.settings-panel.hidden { display: none; }
.settings-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-family: var(--font-ui);
  font-size: 13px;
  font-weight: 700;
  color: var(--text);
  margin-bottom: var(--s4);
}
.settings-label {
  display: block;
  font-family: var(--font-ui);
