  color: var(--mute);
  margin-bottom: var(--s1);
  letter-spacing: var(--label-spacing);
}
.settings-input {
  width: 100%;
  box-sizing: border-box;
  padding: 8px 10px;
  font-family: var(--font-ui);
  font-size: 12px;
  color: var(--text);
