  els.settingsUrl.value = state.config.apiBaseUrl;
  els.settingsPanel.classList.remove("hidden");
});
els.settingsClose.addEventListener("click", () => {
  els.settingsPanel.classList.add("hidden");
});
els.settingsSave.addEventListener("click", () => {
  const url = els.settingsUrl.value.trim().replace(/\/$/, "");
  if (!url) return;
  state.config.apiBaseUrl = url;
  try { localStorage.setItem("widgetApiBaseUrl", url); } catch {}
  els.settingsPanel.classList.add("hidden");
  showToast("地址已更新");
  loadDigest(true);
});

els.openWeb.addEventListener("click", () => openLink(state.config.apiBaseUrl));
